INSERT INTO knowledge_base (content, source_name, source_page, subject, embedding) VALUES ('في الرياضيات، يشير التفاضل إلى عدة مفاهيم مترابطة مستمدة من الأيام الأولى لحُسْبَان التفاضل والتكامل، والتي وضعت على أساس صارم، مثل الفروق اللامتناهية في الصغر ومشتقات الدوال.
يستخدم هذا المصطلح في مختلف فروع الرياضيات مثل حُسْبَان التفاضل والتكامل، والهندسة التفاضلية، والهندسة الجبرية، والطبولوجيا الجبرية .


== مقدمة ==
يُستخدم مصطلح التفاضل بشكل غير دقيق في حسبان التفاضل والتكامل للإشارة إلى تغير لامتناهٍ في الصغر ("صغير لانهائيًا") في بعض الكميات المتغيرة. على سبيل المثال، إذا كان x متغيرًا، فإن التغير في قيمة x يُشار إليه غالبًا بـ Δ x (يُنطق دلتا x). يمثل التفاضل dx تغيرًا لامتناهٍ في الصغر في المتغير x. إن فكرة التغير اللامتناهي في الصغر أو البطيء للغاية مفيدة للغاية بديهيًا، وتوجد عدة طرق لجعل هذا المفهوم دقيقًا من الناحية الرياضياتية.
باستخدام حسبان التفاضل والتكامل، يُمكن ربط التغيرات اللامتناهية في الصغر لمختلف المتغيرات ببعضها البعض رياضيًا باستخدام المشتقات. إذا كانت y دالة لـ x، فإن التفاضل dy لـ y يرتبط بـ dx بالصيغة:
  
    
      
